\begin{definition}[Excess and relative excess]
For a rung with perplexity $P$, the \emph{excess perplexity} is $E = P - 6.9825$
and the \emph{relative excess} is $E/6.9825$.
\end{definition}

To keep bit-width gaps integral we measure precision in tenths of a bit; rung $X$
has $\mathrm{tb}(X) \in \{85,66,55,48,39,26\}$.

\begin{definition}[The ladder]
The \emph{ladder} is the list of rungs $\mathrm{B},\mathrm{C},\mathrm{D},
\mathrm{E},\mathrm{F}$, with excesses $0.0181$, $0.0602$, $0.1268$, $0.2933$,
$1.1280$. Rung A is excluded: its perplexity lies \emph{below} the reference
(Proposition~\ref{prop:scorecard}), so it carries no multiplicative signal.
\end{definition}

\begin{proposition}[Positivity]
Every rung of the ladder has $E>0$.
\end{proposition}

\subsection{The one-parameter geometric law}

\begin{theorem}[Geometric Ladder Law]\label{thm:band}
Let $r,s$ be rungs of the ladder with $\mathrm{tb}(s)<\mathrm{tb}(r)$, and let
$k = \mathrm{tb}(r)-\mathrm{tb}(s)$ be their gap in tenths of a bit. Then
\[
\left(\tfrac52\right)^{k} E(r)^{10} \;\le\; E(s)^{10} \;\le\; 3^{k} E(r)^{10}.
\]
Equivalently, with $\Delta b = k/10$ the gap in bits,
$\tfrac52 \le \big(E(s)/E(r)\big)^{1/\Delta b} \le 3$.
\end{theorem}

\begin{proof}[Proof sketch]
The statement is a finite conjunction of ten rational inequalities, one per
ordered pair of distinct rungs. Raising the per-bit ratio bound to the power
$10\Delta b = k$ clears the fractional exponent into integer arithmetic, and each
resulting inequality is verified exactly on the measured rationals.
\end{proof}

\begin{remark}
The law is genuinely global: the same band $[5/2,3]$ covers all ten pairs,
including the widest ($6.6\to 2.6$ bpw, a four-bit gap), not merely the four
adjacent ones. Thus $E(b) \asymp C m^{-b}$ with $m \in [5/2,3]$ describes the
whole measured range. The extreme observed per-bit rates are $2.539$
($\mathrm{D}\to\mathrm{E}$) and $2.982$ ($\mathrm{B}\to\mathrm{C}$), so neither
endpoint of the band has much slack.
\end{remark}

\begin{theorem}[Cliff-freeness, monotonicity, convexity]\label{thm:shape}
For all rungs of the ladder:
\begin{enumerate}
\item if $\mathrm{tb}(s)<\mathrm{tb}(r)$ with gap $k$ then $E(s)^{10} < 4^{k}E(r)^{10}$:
no pair reaches a per-bit degradation factor of $4$;
\item if $\mathrm{tb}(s)<\mathrm{tb}(r)$ then $E(r)<E(s)$;
\item for rungs $a,b,c$ with $\mathrm{tb}(a)<\mathrm{tb}(b)<\mathrm{tb}(c)$,
\[
\big(E(b)-E(a)\big)\big(\mathrm{tb}(c)-\mathrm{tb}(b)\big)
\;<\;
\big(E(c)-E(b)\big)\big(\mathrm{tb}(b)-\mathrm{tb}(a)\big),
\]
i.e.\ all ten triples of secant slopes are increasing in bit width.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
(1) follows from the upper half of Theorem~\ref{thm:band} with $3^k<4^k$ for
$k\ge 1$ and $E(r)^{10}>0$; (2) and (3) are finite conjunctions of exact rational
inequalities over the measured values.
\end{proof}

The constant $4$ in part (1) is not aesthetic: Section~\ref{sec:curv} shows it is
the exact per-bit multiplier predicted by second-order theory.

\subsection{The pre-registered scorecard}

\begin{proposition}[Scorecard]\label{prop:scorecard}
\begin{enumerate}
\item (P1, confirmed.) Rung B lies inside the $\pm0.5\%$ band around the
reference: $|E/6.9825|<1/200$ (measured $+0.259\%$).
\item (P2, refuted narrowly.) Rung E was predicted in $[+5\%,+30\%]$; it landed
at $+4.2005\%$, strictly between $+2\%$ and $+5\%$, refuting both that band and
the competing ``erased, i.e.\ under $+2\%$'' reading.
\item (P3, refuted decisively.) Rung F was predicted undeployable at $\ge +50\%$;
the measured cost is $+16.155\%$, under $+20\%$.
\item Rung A's relative excess is negative and under $0.1\%$ in magnitude.
\item Rung D's cost plus the measured $+0.14\%$ of an $8$-bit-key/$4$-bit-value
attention cache is under $2\%$ in aggregate.
\end{enumerate}
\end{proposition}

\subsection{Why a geometric band forbids a floor}

\begin{theorem}[Geometric closure]\label{thm:closure}
Let $D:\mathbb{N}\to\mathbb{R}$ assign a degradation to each precision (indexed in
tenths of a bit), let $m\ge 0$, and suppose $D(b)\le m\,D(b+10)$ for all $b$. Then
for every $b$ and every $k$, $D(b) \le m^{k} D(b+10k)$.
\end{theorem}

\begin{proof}
Induction on $k$. The base case is trivial; for the step, apply the hypothesis at
$b+10k$ and multiply by $m^{k}\ge 0$.
\end{proof}

\begin{corollary}[Bounded damage below an anchor]
Under the hypotheses of Theorem~\ref{thm:closure}, if $D(\text{anchor})\le d_0$
then either $D(\text{anchor}-10k)\le m^{k}d_0$, or $10k$ exceeds the anchor.
\end{corollary}

A floor at a finite bit width would require degradation to diverge, or to jump by
an unbounded factor, at that width; both are forbidden for every finite $k$.

\begin{corollary}[Conditional one-bit extrapolation]\label{cor:extrap}
Suppose the fitted upper rate $m=3$ persists below the lowest measured rung and
$D(2.6\ \mathrm{bpw})\le 1.1280$. Then $D(1.6\ \mathrm{bpw}) < \tfrac12\cdot 6.9825$:
a full bit below anything measured, the relative excess is still under the $+50\%$
threshold, since $3\times 1.1280 = 3.384 < 3.49125$.
\end{corollary}

\section{The curvature model: a four-per-bit ceiling, and quality as bits}
\label{sec:curv}

\begin{definition}[Quadratic excess]
For curvatures $\lambda\in\mathbb{R}^n$ and a perturbation $e\in\mathbb{R}^n$ in
the Hessian eigenbasis, the modelled loss increase is
$Q_\lambda(e) = \tfrac12\sum_{i=1}^{n}\lambda_i e_i^2$.
\end{definition}

\begin{proposition}
If $\lambda_i\ge 0$ for all $i$ then $Q_\lambda(e)\ge 0$.
\end{proposition}

\begin{definition}[Curvature bound]
For $K\in\mathbb{R}$ and bit width $b$, $\CB(K,b) = K/4^{\,b}$.
\end{definition}

\begin{theorem}[Curvature bound for a $b$-bit quantiser]
Let $0\le\lambda_i\le\Lambda$ for all $i$, and let a $b$-bit quantiser with
dynamic-range constant $c$ produce coordinatewise errors $|e_i|\le c/2^{\,b}$.
Then $Q_\lambda(e) \le \CB\!\big(n\Lambda c^2/2,\;b\big)$.
\end{theorem}

\begin{proof}[Proof sketch]
Termwise, $\lambda_i e_i^2 \le \Lambda(c/2^b)^2 = \Lambda c^2/4^b$; sum over the
$n$ coordinates and halve.
\end{proof}

\begin{theorem}[Exact per-bit multiplier]\label{thm:fourperbit}
For all $K$ and $b$, $\CB(K,b) = 4\,\CB(K,b+1)$.
\end{theorem}

Thus in the second-order world removing one bit multiplies modelled damage by
exactly $4$: four is the theoretical worst case for smooth quantisation damage.

\begin{theorem}[The data beats the ceiling]
Every pair of rungs of the measured ladder degrades strictly slower than the
$4$-per-bit ceiling; measured per-bit rates lie in $[2.539,2.982]$.
\end{theorem}

\begin{proof}
This is Theorem~\ref{thm:shape}(1).
\end{proof}

Calibration-aware quantisers therefore recover a factor the naive bound does not
model: the bound assumes the worst about the alignment of quantisation error with
high-curvature directions, whereas a calibrated quantiser deliberately spends
resolution where curvature is large.

\begin{proposition}[Shape of the model curve]
For $K>0$, $\CB(K,\cdot)$ is strictly decreasing in $b$ and strictly
midpoint-convex,
$2\CB(K,b+1) < \CB(K,b)+\CB(K,b+2)$, with gap $9K/(16\cdot 4^{b})$; and its
continuous extension $b \mapsto K e^{-(\log 4)b}$ is convex on $\mathbb{R}$ for
$K\ge 0$.
\end{proposition}

\begin{theorem}[Quality is a bit shift]\label{thm:qualitybits}
For all $n,\Lambda,c$ and all $j,b\in\mathbb{N}$,
\[
\CB\!\left(\frac{n\Lambda(c/2^{\,j})^2}{2},\,b\right)
=
\CB\!\left(\frac{n\Lambda c^2}{2},\,b+j\right).
\]
A quantiser $2^{\,j}$ times more accurate is worth exactly $j$ bits.
\end{theorem}

\begin{proof}
$(c/2^j)^2 = c^2/4^j$ and $4^{b+j} = 4^b4^j$; the two factors of $4^j$ cancel.
\end{proof}

\begin{theorem}[No intrinsic floor]
Let $n,\Lambda\ge 0$, fix any bit width $b$ and any tolerance $T>0$. Then there
exists $j\in\mathbb{N}$ with
$\CB\big(n\Lambda(c/2^{\,j})^2/2,\;b\big) \le T$.
\end{theorem}

\begin{proof}[Proof sketch]
Since $4^j\to\infty$ there is a $j$ with $\CB(n\Lambda c^2/2,\;j)\le T$; apply
Theorem~\ref{thm:qualitybits} and note $4^{j}\le 4^{b+j}$.
\end{proof}

\begin{corollary}[The floor is not a bit-width law]
No bit width is intrinsically undeployable. A floor observed at width $b$ with a
given quantiser is displaced to width $b-j$ by any quantiser $2^{\,j}$ times more
accurate.
\end{corollary}

\section{Separating the confound: block scaling is worth $\log_2(R/\rms)$ bits}

Partition a weight tensor into $B$ blocks; let $r_i\ge 0$ be the dynamic range of
block $i$ and $R=\max_i r_i$. A $b$-bit uniform quantiser with a single
tensor-wide scale has per-coordinate error proportional to $R/2^{\,b}$: one
outlier anywhere coarsens the grid everywhere. With a per-block scale, block $i$
has error proportional to $r_i/2^{\,b}$, so the mean square error is governed by
the root mean square of the block ranges.

\begin{definition}
$\msq(r) = \frac1B\sum_{i=1}^{B} r_i^2$ and $\rms(r) = \sqrt{\msq(r)}$.
\end{definition}

\begin{definition}[Scale gain]
$G(r,R) = R/\rms(r)$: the factor by which the effective dynamic range shrinks
when a global scale is replaced by per-block scales.
\end{definition}

\begin{theorem}[Blocking never hurts]
If $B>0$ and $0\le r_i\le R$ for all $i$, then $\rms(r)\le R$, and hence
$G(r,R)\ge 1$ whenever $\rms(r)>0$.
\end{theorem}

\begin{proof}[Proof sketch]
$\sum_i r_i^2 \le BR^2$ termwise, so $\msq(r)\le R^2$; take square roots.
\end{proof}

\begin{theorem}[Single-term bound]
For any index $i_0$ and nonnegative ranges, $r_{i_0} \le \sqrt{B}\,\rms(r)$.
\end{theorem}

\begin{proof}[Proof sketch]
$r_{i_0}^2 \le \sum_i r_i^2 = B\,\msq(r)$; take square roots and use
$\sqrt{B\,\msq(r)} = \sqrt{B}\,\rms(r)$.
\end{proof}

\begin{theorem}[The block-scaling budget]\label{thm:budget}
If the maximum $R$ is attained by some block and $\rms(r)>0$, then
$1 \le G(r,R) \le \sqrt{B}$.
\end{theorem}

\begin{theorem}[The budget is exactly outlier concentration]\label{thm:outlier}
Let $R>0$ and let $r_i = R$ for a single index $i_0$ and $r_i=0$ otherwise. Then
$G(r,R)=\sqrt{B}$ exactly.
\end{theorem}

\begin{proof}[Proof sketch]
$\sum_i r_i^2 = R^2$, so $\msq(r)=R^2/B$ and $\rms(r)=R/\sqrt{B}$.
\end{proof}

Theorems~\ref{thm:budget} and \ref{thm:outlier} say that the entire advantage of
calibration-aware block quantisation over naive global-scale rounding is a
statement about the outlier profile of the weights: equal block ranges give gain
exactly $1$, single-block concentration gives the maximum.

\begin{theorem}[Block scaling is a bit shift]\label{thm:blockshift}
If $R = 2^{\,j}\rms(r)$ then for every $b$,
$\rms(r)^2/4^{\,b} = R^2/4^{\,b+j}$: a scale gain of $2^{\,j}$ translates the whole
degradation curve by exactly $j$ bits.
\end{theorem}

\begin{theorem}[The $B=256$ budget]
At the standard block size $B=256$, whatever the range profile,
$G(r,R) \le \sqrt{256} = 16 = 2^{4}$: per-block scaling is worth at most four
bits.
\end{theorem}

\begin{theorem}[The observed shift fits the budget]
The naive global-scale floor sat at $6.0$ bpw; the calibration-aware ladder
remains deployable at $2.6$ bpw. The shift is $3.4$ bits, strictly inside the
four-bit budget, and the budget is attained under single-block outlier
concentration --- precisely the regime large weight tensors are known to occupy.
\end{theorem}

\begin{corollary}
The collapse of the weight floor is fully accountable by quantiser quality alone;
the $14\times$ increase in model scale is not required to explain it.
\end{corollary}

This does not prove scale irrelevant; it proves scale is not \emph{needed}, and it
converts the documented confound into the falsifiable prediction of
Section~\ref{sec:future}.

\section{Selection versus content: why some axes cliff and others cannot}

\begin{definition}
A quantiser $q:\mathbb{R}\to\mathbb{R}$ is \emph{$\delta$-accurate} if
$|q(x)-x|\le\delta$ for all $x$. A vector $p\in\mathbb{R}^n$ is a
\emph{probability weight vector} if $p_i\ge 0$ and $\sum_i p_i = 1$. Write
$\langle p,v\rangle = \sum_i p_iv_i$, and $\Top(u,i)$ for the assertion that
$u_i>u_j$ for all $j\ne i$.
\end{definition}

\begin{theorem}[Content error bound]\label{thm:content}
If $p$ is a probability weight vector and $q$ is $\delta$-accurate, then for every
$v\in\mathbb{R}^n$,
$\big|\langle p,q\circ v\rangle - \langle p,v\rangle\big| \le \delta$.
\end{theorem}

\begin{proof}
The difference is $\sum_i p_i(q(v_i)-v_i)$, bounded by
$\sum_i p_i|q(v_i)-v_i| \le \delta\sum_i p_i = \delta$.
\end{proof}

\begin{theorem}[Sharpness]
For every $\delta\ge 0$ there exist $p$, $v$ and a $\delta$-accurate $q$ attaining
equality: take $n=1$, $p=(1)$, $v=(0)$, $q(x)=x+\delta$.
\end{theorem}

\begin{theorem}[A flip at every precision]\label{thm:flip}
For every $\delta>0$ and every $C\ge 0$ there exist scores $u\in\mathbb{R}^2$,
values $\mathrm{val}\in\mathbb{R}^2$, and a $\delta$-accurate quantiser $q$ with
$\Top(u,0)$, $\Top(q\circ u,1)$, $|\mathrm{val}_1-\mathrm{val}_0| = C$ and
$u_0-u_1\le\delta$.
\end{theorem}

\begin{proof}[Proof sketch]
Take $u=(\delta/2,0)$, $\mathrm{val}=(0,C)$ and
$q(x)=x+\delta/2$ for $x\le\delta/4$, $q(x)=x-\delta/2$ otherwise. Then
$|q(x)-x|=\delta/2\le\delta$ everywhere, while $q(u_0)=0$ and $q(u_1)=\delta/2$,
so the ranking reverses.
\end{proof}

\begin{theorem}[No modulus of continuity]
For every proposed bound $f:\mathbb{R}\to\mathbb{R}$ and every $\delta>0$ there is
a configuration as in Theorem~\ref{thm:flip} whose read-out error strictly exceeds
$f(\delta)$.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:flip} with $C = |f(\delta)|+1$.
\end{proof}

\begin{theorem}[The dissociation]
Fix any $\delta>0$. Simultaneously: every probability-weighted content read-out
under a $\delta$-accurate quantiser moves by at most $\delta$; and there is a
selection read-out under a $\delta$-accurate quantiser that moves by any
prescribed amount $C$.
\end{theorem}

In slogan form: \emph{selection interfaces carry precision requirements; content
containers do not.} Selection error is $\Theta(1)$ where content error is
$\Theta(\delta)$.

\begin{theorem}[Enough bits]\label{thm:enough}
Let $u$ have top index $i$ with margin $g$, i.e.\ $u_i-u_j\ge g$ for all $j\ne i$,
and let $q$ be $2^{-b}$-accurate. If $2\cdot 2^{-b} < g$ then $\Top(q\circ u,i)$.
\end{theorem}

\begin{theorem}[Too few bits]
For every $b$ and every $C\ge 0$ there is a configuration with margin
$\le 2^{-b}$, a $2^{-b}$-accurate quantiser reversing the top-$1$ decision, and
read-out error exactly $C$.
\end{theorem}

These pin the transition at $b\approx\log_2(1/g)$: a property of the margin
distribution of the scores, not of the tensor being quantised. Above the
threshold the error is $0$; below it, $\Theta(1)$. That is a wall, not a slope.

\begin{theorem}[Flip counting]\label{thm:flipcount}
Let $u_\ell\in\mathbb{R}^n$ be the score vectors at positions $\ell=1,\dots,L$
with intended top indices $i_\ell$, and let $q$ be $\varepsilon$-accurate. Then
\[
\#\{\ell : \Top(q\circ u_\ell, i_\ell)\text{ fails}\}
\;\le\;
\#\{\ell : \exists j\ne i_\ell,\ u_\ell(i_\ell)-u_\ell(j)\le 2\varepsilon\}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Contrapositive, position by position: if every competitor is more than
$2\varepsilon$ below the top, the margin certificate of Theorem~\ref{thm:enough}
applies, so the broken positions inject into the small-margin positions.
\end{proof}

\begin{corollary}[The cliff is a CDF]
Degradation on a selection axis tracks the cumulative distribution function of the
top-$1$ margin evaluated at $2\varepsilon$. If margins concentrate in a narrow
band, that CDF has a near-vertical segment and the system inherits a
near-vertical degradation curve over a single bit.
\end{corollary}

The weight path contains no $\arg\max$, so Theorem~\ref{thm:content} applies end
to end and no cliff is available to it.

\section{Composing compressions: the stack budget is a seminorm}

\begin{definition}
The curvature pairing is $\Pi_\lambda(e,f) = \tfrac12\sum_i \lambda_i e_i f_i$, so
that $Q_\lambda(e+f) = Q_\lambda(e)+Q_\lambda(f)+2\Pi_\lambda(e,f)$.
\end{definition}

\begin{theorem}[Cauchy--Schwarz in the curvature metric]
If $\lambda_i\ge 0$ for all $i$, then
$\Pi_\lambda(e,f)^2 \le Q_\lambda(e)Q_\lambda(f)$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply the discrete Cauchy--Schwarz inequality to $(\sqrt{\lambda_i}e_i)$ and
$(\sqrt{\lambda_i}f_i)$; degenerate directions $\lambda_i=0$ are permitted.
\end{proof}

\begin{theorem}[Triangle inequality]
Under the same hypothesis,
$\sqrt{Q_\lambda(e+f)} \le \sqrt{Q_\lambda(e)}+\sqrt{Q_\lambda(f)}$.
\end{theorem}

\begin{theorem}[Two-axis budget]
If $Q_\lambda(e_w)\le a$ and $Q_\lambda(e_c)\le b$ then
$Q_\lambda(e_w+e_c) \le a+b+2\sqrt{ab}$, whatever the correlation between the two
perturbations.
\end{theorem}

\begin{corollary}[The measured stack]
With $a=1.816\%$ (weights at $4.8$ bpw) and $b=0.14\%$ (an
$8$-bit-key/$4$-bit-value cache), the composed stack costs strictly under $3\%$:
$\sqrt{ab} = 0.504\%$ gives $1.816+0.14+2(0.504) = 2.964 < 3$.
\end{corollary}

\begin{theorem}[Exact additivity under orthogonality]
If $\Pi_\lambda(e_w,e_c)=0$ --- the natural ``independent compressions''
hypothesis --- then $Q_\lambda(e_w+e_c) = Q_\lambda(e_w)+Q_\lambda(e_c)$ exactly.
\end{theorem}

At the measured numbers this predicts $1.816\%+0.14\% = 1.956\%$ for the joint
arm, against a worst-case guarantee of under $2.964\%$. The gap between these two
numbers is an experiment.

\section{Algorithms}

\paragraph{Per-bit rate extraction and band certification.}
Given rungs $(b_i,P_i)$ and a reference $P_0$, form $E_i = P_i-P_0$, discard any
rung with $E_i\le 0$ as noise, and for every ordered pair compute the implied
per-bit rate $m_{ij} = (E_j/E_i)^{1/(b_i-b_j)}$ for $b_j<b_i$. Certify the band
over all $\binom{k}{2}$ pairs, at cost $O(k^2)$. Reporting all pairs rather than
adjacent ones is what distinguishes a genuine one-parameter law from a piecewise
fit: a hidden cliff shows up as a wide-pair rate escaping the adjacent-pair band.

\paragraph{Block-scaling gain audit.}
Given a weight tensor and block size $B$, compute each block's dynamic range
$r_i$, then $G = \max_i r_i/\rms(r)$ and the bit gain $\log_2 G$. By
Theorem~\ref{thm:budget}, $0\le\log_2 G\le\tfrac12\log_2 B$; by
Theorem~\ref{thm:blockshift} this is the exact horizontal translation block
quantisation buys at the same bit width. Cost: one pass over the tensor, and no
perplexity evaluation at all.

\paragraph{Margin-CDF cliff prediction.}
Given attention score vectors at $L$ positions, compute the top-$1$ margins, sort,
and evaluate the empirical CDF at $2\cdot 2^{-b}$ for each candidate $b$. By
Theorem~\ref{thm:flipcount} this upper-bounds the fraction of decisions a $b$-bit
quantiser can break; by Theorem~\ref{thm:enough} the remaining positions are
provably safe. Cost $O(Ln)$ plus $O(L\log L)$, from a single forward pass.

\section{Discussion, limits, and future directions}\label{sec:future}

\subsection{Honest limits}
The measurement is a single model family on a single held-out slice with a single
family of calibrations, and per-arm standard errors were not captured. The
$-0.063\%$ at $8.5$ bpw is treated as within noise and excluded from the
multiplicative law on that basis. The comparison against the naive global-scale
baseline crosses quantiser quality \emph{and} model scale simultaneously; the
block-scaling analysis quantifies the quality half and shows it suffices, but does
not perform the separation experiment. One reassuring datum: the $4.8$ bpw arm
reproduced an independent earlier run's perplexity of $7.1093$ exactly.

\subsection{Practical consequence}
Weights at $4.8$ bpw ($+1.816\%$), an $8$-bit-key/$4$-bit-value attention cache
($+0.14\%$), and speculative decoding compose into a serving stack at roughly
one-eighth of the naive memory footprint for an aggregate quality cost under
$2\%$, on commodity CPU hardware. The design rule the theory recommends is blunt:
spend precision at selection interfaces and economise everywhere else.

\subsection{Future directions}
\begin{enumerate}
\item \textbf{Margin-CDF law for the key cliff.} The cache-key cliff should be the
CDF of the top-$1$ attention margin evaluated at $2\cdot 2^{-b}$; measuring the
margin distribution of one model should predict the cliff location of every
quantiser applied to it. The histogram is one forward pass away, and
Theorem~\ref{thm:flipcount} turns it into a prediction.
\item \textbf{Naive rounding versus block quantisation at fixed scale.}
Theorem~\ref{thm:blockshift} converts the quality half of the confound into the
single measurable number $\log_2(R/\rms(r))$, computable from the weight tensors
alone. The prediction is a rigid horizontal translation of the whole ladder, by at
most four bits at $B=256$.
\item \textbf{The joint stack arm.} A guarantee of under $2.964\%$ against a sharp
prediction of $1.956\%$ under curvature-orthogonality: measuring the joint arm
reads off the alignment of the two perturbations.
\item \textbf{Extending the ladder below $2.6$ bpw.} Corollary~\ref{cor:extrap}
predicts that even at $1.6$ bpw the relative excess stays under $+50\%$ if the
fitted rate $m=3$ persists; this is the cleanest available falsification.
\item \textbf{Curvature-rate reconciliation.} The model ceiling is $4$ per bit; the
data runs at $2.54$--$2.98$. Quantifying the residual --- the ratio between naive
dynamic range and calibration-weighted effective range in high-curvature
directions --- would turn the ceiling into an estimate rather than a bound.
\end{enumerate}

\section{Conclusion}

The sub-six-bit weight floor is not a law about bit widths. It is a law about
quantisers, and quantiser quality is measured in bits: a quantiser $2^{\,j}$ times
more accurate is worth exactly $j$ bits, and per-block scaling with $B$ blocks is
worth $\log_2(R/\rms(r)) \le \tfrac12\log_2 B$ bits, attained exactly under
single-block outlier concentration. Four bits of budget at the standard block size
comfortably covers the $3.4$-bit shift observed. What remains is a smooth
one-parameter geometric law: excess perplexity multiplies by between $2.5$ and $3$
per bit removed, across every pair of measured precisions from $6.6$ down to $2.6$
bits per weight, strictly inside the four-per-bit ceiling second-order theory
imposes. Where genuine cliffs do occur, they occur for a reason that is now a
theorem: numbers consumed by averaging have a sharp modulus of continuity in the
quantiser step; numbers consumed by ranking have none, at any precision.

